(7671287, 1251903, 65234, '<td valign="top">Beautiful portrait of a hawk. Their gaze always seems so intense.</td>', 'Beautiful portrait of a hawk. Their gaze always seems so intense.', '2020-08-01 09:13:46.000000', NULL, 1),
(7671288, 1252689, 65234, '<td valign="top">Love the pose and the pastels. An out-of-the-ordinary heron image.</td>', 'Love the pose and the pastels. An out-of-the-ordinary heron image.', '2020-08-01 09:14:33.000000', NULL, 1),
(7671289, 1252306, 156466, '<td valign="top">Spectacular capture. Wish you had spent some time burning in the background a bit to better isolate the Croc.</td>', 'Spectacular capture. Wish you had spent some time burning in the background a bit to better isolate the Croc.', '2020-08-01 09:14:58.000000', NULL, 1),
(7671290, 1251947, 65234, '<td valign="top">Love the speed you used to keep some turbulence in the water, and the color palette. I''ve seen a million of these sorts of images but I still appreciate a good one, and this is.</td>', 'Love the speed you used to keep some turbulence in the water, and the color palette. I''ve seen a million of these sorts of images but I still appreciate a good one, and this is.', '2020-08-01 09:16:03.000000', NULL, 1),
(7671291, 1252675, 65234, '<td valign="top">A truly WOW macro.</td>', 'A truly WOW macro.', '2020-08-01 09:16:34.000000', NULL, 1),
(7671292, 1252458, 65234, '<td valign="top">Nicely captured with just a hint of motion blur.</td>', 'Nicely captured with just a hint of motion blur.', '2020-08-01 09:17:09.000000', NULL, 1),
(7671293, 1252369, 65234, '<td valign="top">What a lovely, peaceful scene to wake up to. Love the golden warmth of the light.</td>', 'What a lovely, peaceful scene to wake up to. Love the golden warmth of the light.', '2020-08-01 09:17:45.000000', NULL, 1),
(7671294, 1252533, 65234, '<td valign="top">I''m impressed that the stargazer was able to hold so still so you could get a nice, sharp sky. The flashlight adds interest there.</td>', 'I''m impressed that the stargazer was able to hold so still so you could get a nice, sharp sky. The flashlight adds interest there.', '2020-08-01 09:18:59.000000', NULL, 1),
